from abc import ABC, abstractmethod


class OpticalSwitch(ABC):
    def __init__(self, host, port=None, timeout=None):
        self._host = host
        self._port = port
        self._timeout = timeout

    @abstractmethod
    def get_optical_switch_channels(self):
        pass

    @abstractmethod
    def set_optical_switch_channels(self, new_settings):
        pass

    @abstractmethod
    def teardown(self):
        """Closes connection with optical switch"""
        pass
